const crypto = require('crypto');

const sharedSecret = $env.TASC_N8N_SHARED_SECRET || '';
const signingSecret = $env.TASC_N8N_SIGNING_SECRET || '';

const qualifiedBands = (($env.TASC_QUALIFIED_BANDS || 'qualified,hot')
  .toLowerCase())
  .split(',')
  .map(s => s.trim())
  .filter(Boolean);

const unwrap = (v) => {
  return (
    v &&
    typeof v === 'object' &&
    !Array.isArray(v) &&
    'value' in v
  )
    ? v.value
    : v;
};

const txt = (v) => {
  const u = unwrap(v);
  return (u === null || u === undefined) ? '' : String(u);
};

const out = [];

for (const item of $input.all()) {

  const headers = item.json.headers || {};
  const body = item.json.body || item.json;

  // ============================================================
  // 1. AUTHENTICATION
  // ============================================================

  if (sharedSecret) {
    const presented =
      headers['x-tasc-shared-secret'] ||
      headers['x-shared-secret'] ||
      '';

    if (presented !== sharedSecret) {
      throw new Error('AUTH_FAILED: shared secret mismatch');
    }
  }

  // ============================================================
  // 2. SIGNATURE VERIFICATION
  // ============================================================

  let signatureState = 'skipped';

  const presentedSig = (
    headers['x-tasc-signature'] ||
    headers['x-signature'] ||
    ''
  ).replace(/^sha256=/, '');

  if (signingSecret && presentedSig) {

    const computed = crypto
      .createHmac('sha256', signingSecret)
      .update(JSON.stringify(body))
      .digest('hex');

    const ok =
      computed.length === presentedSig.length &&
      crypto.timingSafeEqual(
        Buffer.from(computed),
        Buffer.from(presentedSig)
      );

    signatureState = ok ? 'valid' : 'mismatch';

    if (
      !ok &&
      ($env.TASC_N8N_REQUIRE_SIGNATURE || 'false') === 'true'
    ) {
      throw new Error(
        'SIGNATURE_INVALID: HMAC-SHA256 mismatch'
      );
    }
  }

  // ============================================================
  // 3. BASIC PAYLOAD VALIDATION
  // ============================================================

  const sessionId = txt(body.session_id);

  const consultationId =
    txt(body.consultation_id) || sessionId;

  if (!sessionId && !consultationId) {
    throw new Error(
      'VALIDATION_FAILED: session_id or consultation_id is required'
    );
  }

  // ============================================================
  // 4. READ PAYLOAD SECTIONS
  // ============================================================

  const profile = body.business_profile || {};
  const qual = body.lead_qualification || {};
  const conversation = body.conversation || {};

  const contact =
    body.contact ||
    profile.contact ||
    {};

  // ============================================================
  // 5. LEAD QUALIFICATION
  // ============================================================

  const band = txt(
    qual.band || qual.level
  ).toLowerCase();

  const score = Number(
    unwrap(qual.score) ?? 0
  );

  if (!band) {
    throw new Error(
      'VALIDATION_FAILED: lead_qualification band/level is required'
    );
  }

  // ============================================================
  // 6. CONTACT + COMPLETION GATE
  // ============================================================

  const conversationFinished =
    body.conversation_finished === true;

  const hasContactName =
    txt(contact.name).trim().length > 0;

  const hasContactEmail =
    txt(contact.email).trim().length > 0;

  const shouldCreateLead =
    qualifiedBands.includes(band) &&
    conversationFinished &&
    hasContactName &&
    hasContactEmail;

  // ============================================================
  // 7. PAIN POINTS
  // ============================================================

  const painPoints = (
    profile.pain_points || []
  )
    .map(p =>
      typeof p === 'string'
        ? p
        : txt(p.description)
    )
    .filter(Boolean);

  // ============================================================
  // 8. RECOMMENDATIONS
  // ============================================================

  const recommendations = (
    body.recommendations || []
  ).map(r => ({
    name: txt(
      r.name ||
      r.service_name ||
      r.service
    ),

    rank: unwrap(
      r.priority_rank ??
      r.priority
    ) ?? null,

    confidence: unwrap(
      r.confidence
    ) ?? null,

    rationale: txt(
      r.rationale ||
      r.reason
    )
  }));

  // ============================================================
  // 9. OUTPUT
  // ============================================================

  out.push({
    json: {

      // Routing
      is_qualified: shouldCreateLead,

      idempotency_key:
        `${consultationId}::log_lead`,

      // Provenance
      signature_state: signatureState,

      received_at:
        new Date().toISOString(),

      response_type:
        txt(body.response_type),

      turn_index:
        unwrap(body.turn_index) ?? null,

      // Identity
      session_id:
        sessionId,

      consultation_id:
        consultationId,

      // Qualification
      band:
        band,

      score:
        score,

      justification:
        txt(qual.justification),

      // Contact
      contact_name:
        txt(contact.name),

      contact_email:
        txt(contact.email),

      company:
        txt(contact.company),

      // Business profile
      industry:
        txt(profile.industry),

      company_size:
        txt(profile.company_size),

      timeline:
        txt(
          profile.timeline ||
          body.timeline
        ),

      budget:
        txt(
          profile.budget_band ||
          profile.budget ||
          body.budget
        ),

      decision_role:
        txt(profile.decision_maker),

      current_tools:
        (
          profile.current_tools ||
          profile.current_systems ||
          []
        )
          .map(txt)
          .join(', '),

      // Pain points
      pain_points:
        painPoints,

      pain_points_text:
        painPoints.join(' | '),

      // Recommendations
      recommendations:
        recommendations,

      recommendations_text:
        recommendations
          .map(r =>
            `${r.name}${
              r.confidence
                ? ` (${r.confidence})`
                : ''
            }`
          )
          .join(', '),

      // Conversation
      assistant_message:
        txt(
          conversation.message ||
          body.assistant_message
        )
    }
  });
}

return out;

