const src = $('Validate & Normalize').first().json;
const dispatched = src.is_qualified;

return [{
  json: {
    status: 'acknowledged',
    consultation_id: src.consultation_id,
    session_id: src.session_id,
    band: src.band,
    score: src.score,
    signature_state: src.signature_state,
    workflow_actions: dispatched ? [
      { action_type: 'log_lead', target_system: 'google_sheets', status: 'dispatched', idempotency_key: `${src.consultation_id}::log_lead` },
      { action_type: 'send_notification_email', target_system: 'gmail', status: 'dispatched', idempotency_key: `${src.consultation_id}::send_notification_email` },
      { action_type: 'send_notification_email', target_system: 'internal_alert', status: 'dispatched', idempotency_key: `${src.consultation_id}::telegram_alert` }
    ] : [
      { action_type: 'none', target_system: 'internal_alert', status: 'skipped_duplicate', trigger_condition: `band=${src.band} below qualification threshold`, idempotency_key: `${src.consultation_id}::none` }
    ]
  }
}];
